components/custom/cart/cart:
{{#if cart.items.length}}
<div class="container floating-checkout-button">
    <a href="#cart-totals" class="button button--primary" title="{{lang 'cart.checkout.title'}}" tabindex="0">{{lang
        'cart.checkout.button'}}</a>
</div>
{{/if}}

<div class="cart__container">
    <div data-cart-content class="cart__content">
        {{> components/custom/cart/content}}
    </div>

    <div data-cart-items style="display:none;">{{json cart.items}}</div>

    <div class="cart__totals js-cart__totals" id="cart-totals">
        <div class="cart__totals-wrapper">
            <div class="cart__totals-header">
                <h2 class="cart__totals-heading h4">
                    {{lang 'common.summary'}}
                </h2>
                <div class="cart__totals-action-container">
                    <a class="cart__totals-action cart__totals-action--cs" href="/">{{lang
                        'custom.cart.back-to-shopping.text'}}</a>
                </div>
            </div>
            <div data-cart-totals class="cart__totals-container">
                {{> components/custom/cart/totals}}
            </div>
            <div class="cart__buttons">
                {{#if cart.show_primary_checkout_button}}
                <div class="cart__actions">
                    <a class="button button--primary" href="{{urls.checkout.single_address}}"
                        title="{{lang 'cart.checkout.title'}}">{{lang 'cart.checkout.button'}}</a>
                    {{#if cart.show_multiple_address_shipping}}
                    <a class="checkoutMultiple" href="{{urls.checkout.multiple_address}}">
                        {{lang 'cart.preview.checkout_multiple'}}
                    </a>
                    {{/if}}
                </div>
                {{else}}
                <div class="cart__actions">
                    <a class="button" href="{{urls.home}}" title="{{lang 'cart.continue_shopping'}}">{{lang
                        'cart.continue_shopping'}}</a>
                </div>
                {{/if}}

                <div data-cart-additional-checkout-buttons
                    class="cart-additionalCheckoutButtons cart-content-padding-right">
                    {{> components/cart/additional-checkout-buttons}}
                </div>
            </div>
        </div>
    </div>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/lottie-web/5.12.2/lottie.min.js"></script>
<script>
    let matchedItems = []; // Store BPN matched items (2952, 2956)
    let allCartItems = []; // Store all cart items for pricing

    async function getCart() {
        try {
            const response = await fetch('/graphql', {
                method: 'POST',
                credentials: 'same-origin',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer {{ settings.storefront_api.token }}'
                },
                body: JSON.stringify({
                    query: `query getCart {
                    site {
                        cart {
                            lineItems {
                                physicalItems {
                                    name
                                    sku
                                    productEntityId
                                    variantEntityId
                                    quantity
                                    imageUrl
                                    catalogProductWithOptionSelections {
                                        prices {
                                            retailPrice {
                                                value
                                            }
                                            salePrice {
                                                value
                                            }
                                            price {
                                                value
                                            }
                                        }
                                    }
                                    originalPrice {
                                        value
                                    }
                                    salePrice {
                                        value
                                    }
                                    retailPrice {
                                        value
                                    }
                                }
                            }
                            id
                        }
                    }
                }`
                })
            });

            const data = await response.json();
            return data;
        } catch (error) {
            console.error(error);
            throw error;
        }
    }

    async function getProductBpn(productId, variantId) {
        const response = await fetch(`https://eomtnzhwpylu4c7.m.pipedream.net?product_id=${productId}&variant_id=${variantId}`);
        const data = await response.json();
        return data.data;
    }

    function calculateItemPrice(item) {
        // Apply same pricing logic as your getCheckout() implementation
        let originalPrice, salePrice;

        let priceOption = item.catalogProductWithOptionSelections;

        if (priceOption) {
            originalPrice = item.catalogProductWithOptionSelections.prices.retailPrice.value * item.quantity;
            salePrice = item.salePrice.value * item.quantity;
        } else {
            originalPrice = item.originalPrice.value * item.quantity;
            salePrice = item.salePrice.value * item.quantity;
        }

        return {
            originalPrice: originalPrice,
            salePrice: salePrice,
            displayPrice: originalPrice > 0 ? originalPrice : salePrice,
            hasDiscount: originalPrice !== salePrice
        };
    }

    async function initializeCart() {
        try {
            // Fetch cart data using GraphQL
            const cartData = await getCart();
            const cartItems = cartData.data.site.cart.lineItems.physicalItems;

            //console.log('Cart items:', cartItems);

            // Store all cart items for pricing
            allCartItems = cartItems.map(item => ({
                sku: item.sku,
                productEntityId: item.productEntityId,
                variantEntityId: item.variantEntityId,
                originalPrice: item.originalPrice,
                salePrice: item.salePrice,
                quantity: item.quantity,
                name: item.name,
                imageUrl: item.imageUrl,
                catalogProductWithOptionSelections: item.catalogProductWithOptionSelections
            }));

            // Find items that need BPN (2952, 2956)
            matchedItems = [];
            for (let item of cartItems) {
                if (item.productEntityId === 2952 || item.productEntityId === 2956) {
                    $('#myLottie').show();
                    matchedItems.push({
                        sku: item.sku,
                        productEntityId: item.productEntityId,
                        variantEntityId: item.variantEntityId,
                        bpn: null
                    });
                }
            }

            // Update pricing for all cart items
            updateAllCartPricing();

            // Handle BPN injection for matched items
            if (matchedItems.length > 0) {
                const bpnPromises = matchedItems.map(item =>
                    getProductBpn(item.productEntityId, item.variantEntityId)
                );

                const responses = await Promise.all(bpnPromises);

                // Update each matched item with its BPN
                matchedItems.forEach((item, index) => {
                    item.bpn = responses[index].bin_picking_number;
                });

                injectBpns(); // inject BPNs for matched items
                $('#myLottie').hide();
            }

        } catch (error) {
            console.error('Error initializing cart:', error);
            $('#myLottie').hide();
        }
    }

    function updateAllCartPricing() {
        isUpdating = true; // Set flag to prevent MutationObserver from triggering

        let cartSubtotal = 0;

        allCartItems.forEach(item => {
            // Calculate pricing for this item using the same logic as getCheckout()
            const pricing = calculateItemPrice(item);
            cartSubtotal += pricing.displayPrice;

            // Find the cart item row
            let cartItemRow = $(`tr.cart-item[data-product-id="${item.productEntityId}"][data-variant-id="${item.variantEntityId}"]`);

            // Alternative selectors for BigCommerce cart
            if (!cartItemRow.length) {
                cartItemRow = $(`tr.cart-item[data-product-id="${item.productEntityId}"]`);
            }
            if (!cartItemRow.length) {
                cartItemRow = $(`[data-item-row]:has([data-product-url*="${item.sku}"])`);
            }

            if (cartItemRow.length) {
                // Update the price display in the cart-item-total cell
                const priceValueSpan = cartItemRow.find('.cart-item-total .cart-item-value');

                if (priceValueSpan.length) {
                    if (pricing.hasDiscount) {
                        // Show both prices on same line, aligned to the right with commas and 2 decimals
                        priceValueSpan.html(`
                        <div class="subtotal--cart">
                            <span class="original-price" style="text-decoration: line-through; color: #999; font-size: 0.9em; margin-right: 8px;">
                                $${pricing.originalPrice.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </span>
                            <span class="sale-price" style="color: #e74c3c; font-weight: bold;">
                                $${pricing.salePrice.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </span>
                        </div>
                    `);
                    } else {
                        // Show single price aligned right with commas and 2 decimals
                        //priceValueSpan.html(`<div class="subtotal--cart">$${pricing.displayPrice.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</div>`);
                    }
                }
            }
        });

        // Update the cart subtotal with commas and 2 decimal places
        $('#cart-rrp-subtotal').text(`$${cartSubtotal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`);

        //console.log('Updated cart subtotal:', cartSubtotal);

        // Reset the flag after a short delay
        setTimeout(() => {
            isUpdating = false;
        }, 100);
    }

    function injectBpns() {
        // Only inject BPNs for matched items (2952, 2956)
        matchedItems.forEach(item => {
            if (!item.productEntityId || !item.bpn) return;

            // Try to find element by both product ID and variant ID
            let elem = $(`[data-product-id="${item.productEntityId}"][data-variant-id="${item.variantEntityId}"] .definitionList`);

            // Fallback: if variant-specific selector doesn't work, try using SKU
            if (!elem.length) {
                elem = $(`[data-sku="${item.sku}"] .definitionList`);
            }

            // Another fallback: find by product ID and then filter by context
            if (!elem.length) {
                $(`[data-product-id="${item.productEntityId}"] .definitionList`).each(function () {
                    const parentElement = $(this).closest('[data-variant-id], [data-sku]');
                    if (parentElement.attr('data-variant-id') == item.variantEntityId ||
                        parentElement.attr('data-sku') == item.sku) {
                        elem = $(this);
                        return false; // break the each loop
                    }
                });
            }

            // Inject BPN with variant-specific data attribute to avoid duplicates
            if (elem.length && !elem.find(`[data-bpn-injected-variant="${item.variantEntityId}"]`).length) {
                elem.append(`
                <dd class="definitionList-value" data-bpn-injected-variant="${item.variantEntityId}">
                    ${item.bpn}
                </dd>
            `);
            }
        });
    }

    // Initialize the cart when page loads
    initializeCart();

    // --- MutationObserver with debounce for cart updates ---
    const targetElem = document.querySelector('[data-cart-content]');
    if (targetElem) {
        let timeout;
        let isUpdating = false; // Flag to prevent infinite loops

        const observer = new MutationObserver((mutations) => {
            // Skip if we're currently updating prices to avoid infinite loop
            if (isUpdating) return;

            // Only trigger on structural changes, not our price updates
            const hasStructuralChanges = mutations.some(mutation => {
                // Check if the mutation is adding/removing cart items, not just updating text content
                return mutation.type === 'childList' &&
                    mutation.addedNodes.length > 0 &&
                    Array.from(mutation.addedNodes).some(node =>
                        node.nodeType === 1 && // Element node
                        (node.classList.contains('cart-item') ||
                            node.querySelector('.cart-item'))
                    );
            });

            if (hasStructuralChanges) {
                clearTimeout(timeout);
                timeout = setTimeout(() => {
                    // Re-fetch and update cart data when cart structure changes
                    initializeCart();
                }, 500);
            }
        });

        observer.observe(targetElem, { childList: true, subtree: true });
    }

    // Lottie animation
    lottie.loadAnimation({
        container: document.getElementById('myLottie'),
        renderer: 'svg',
        loop: true,
        autoplay: true,
        path: 'https://cdn.prod.website-files.com/669591a78e0d5f26fa7c1147/66d6c565c502856051808ecc_Animation%20-%201695777648339.json'
    });

</script>

components/cart/item-giftwrap:
{{#if show_gift_wrapping}}
    <dl class="cart-item-options cart-item-options--giftWrapping">
        <dt class="cart-item-option-title">
            {{lang 'cart.gift_wrapping.title'}}:
        </dt>
        {{#if gift_wrapping}}
            <dd class="cart-item-option-description">
                {{gift_wrapping.name}}: {{gift_wrapping.price.formatted}}
                <span class="cart-item-option-actions">
                    (<a href="" data-item-giftwrap="{{id}}">{{lang 'cart.gift_wrapping.change'}}</a> or <a href="{{gift_wrapping.remove_url}}" onclick="return confirm('{{lang 'cart.gift_wrapping.remove_confirm'}}')">{{lang 'cart.gift_wrapping.remove'}}</a>)
                </span>
            </dd>
            {{#if gift_wrapping.message}}
                <dt class="cart-item-option-title">
                    {{lang 'cart.gift_wrapping.gift_message'}}:
                </dt>
                <dd class="cart-item-option-description">
                    {{gift_wrapping.message}}
                </dd>
            {{/if}}
        {{else}}
            <dd class="cart-item-option-description">
                <a href="" data-item-giftwrap="{{id}}">{{lang 'cart.gift_wrapping.add'}}</a>
            </dd>
        {{/if}}
    </dl>
{{/if}}
